import { FormEvent, ReactNode, useCallback, useEffect, useState } from 'react';
import { api, Batch, Movement, Paginated, Product, ResolvedBatchCode, StockLocation, StockLocationKind, StockPosition, UnitConversion, UserSession } from './api';
import { ConfirmDialog, EmptyState, LoadingState, Notice, PageHeader } from './components';
import { formatDate, formatDateTime } from './format';
import { ExternalExitPage } from './ExternalExitPage';
import { InternalTransferPage, TransferPrefill } from './InternalTransferPage';
import { ReviewPage, ReviewPrefill } from './ReviewPage';

type Page = 'home' | 'operations' | 'new-entry' | 'new-exit' | 'new-transfer' | 'new-review' | 'movements' | 'inventory' | 'products' | 'batches' | 'stocks' | 'more';
type Navigate = (page: Page) => void;
const messageFrom = (error: unknown) => error instanceof Error ? error.message : 'Ocorreu um erro inesperado.';

function Login({ onAuthenticated }: { onAuthenticated: (user: UserSession) => void }) {
  const [username, setUsername] = useState(''); const [password, setPassword] = useState('');
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { onAuthenticated((await api.login(username, password)).user); } catch (caught) { setError(messageFrom(caught)); } finally { setBusy(false); } }
  return <main className="login-page"><section className="login-intro" aria-hidden="true"><p className="brand-mark">ER</p><p className="eyebrow">Estoque Revisao</p><h1>Controle simples para o trabalho diario.</h1><p>Consulte produtos, lotes e saldos com rapidez e rastreabilidade.</p></section><form className="surface login-card" onSubmit={(event) => void submit(event)}><div><p className="eyebrow">Acesso seguro</p><h2>Entrar no sistema</h2><p className="muted">Use seu usuario e senha para continuar.</p></div><label htmlFor="username"><span>Usuario <span className="required">*</span></span></label><input id="username" autoComplete="username" value={username} onChange={(event) => setUsername(event.target.value)} required autoFocus /><label htmlFor="password"><span>Senha <span className="required">*</span></span></label><input id="password" type="password" autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} required />{error && <Notice kind="error">{error}</Notice>}<button className="button-wide" disabled={busy}>{busy ? 'Entrando...' : 'Entrar'}</button></form></main>;
}

function HomePage({ navigate, onTransfer, onReview, inventory, movementsCreate, movementsRead, productsWrite, batchesWrite }: { navigate: Navigate; onTransfer: () => void; onReview: () => void; inventory: boolean; movementsCreate: boolean; movementsRead: boolean; productsWrite: boolean; batchesWrite: boolean }) {
  const [counts, setCounts] = useState({ products: 0, batches: 0, positions: 0 }); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  useEffect(() => { void Promise.all([api.get<Paginated<Product>>('/products?limit=1'), api.get<Paginated<Batch>>('/batches?limit=1'), inventory ? api.get<Paginated<StockPosition>>('/stock-positions?limit=1') : Promise.resolve(null)]).then(([products, batches, positions]) => setCounts({ products: products.meta.total, batches: batches.meta.total, positions: positions?.meta.total ?? 0 })).catch((caught) => setError(messageFrom(caught))).finally(() => setLoading(false)); }, [inventory]);
  return <><PageHeader eyebrow="Inicio" title="O que voce precisa fazer?" description="Acesse rapidamente as funcoes que ja estao disponiveis." />{error && <Notice kind="error">{error}</Notice>}<section className="quick-actions" aria-label="Acoes rapidas">{movementsCreate && <button className="quick-action primary-action" onClick={onReview}><span>Revisar produtos</span><small>Classifique produtos de Revisar entre os destinos permitidos</small></button>}{movementsCreate && <button className="quick-action" onClick={() => navigate('new-entry')}><span>Nova entrada</span><small>Registre produtos recebidos de uma origem externa</small></button>}{movementsCreate && <button className="quick-action" onClick={() => navigate('new-exit')}><span>Nova saida</span><small>Envie produtos com saldo para um destino externo</small></button>}{movementsCreate && <button className="quick-action" onClick={onTransfer}><span>Transferir</span><small>Mova produtos entre locais controlados</small></button>}{movementsRead && <button className="quick-action" onClick={() => navigate('movements')}><span>Historico</span><small>Consulte entradas, saidas, transferencias e revisoes</small></button>}{inventory && <button className="quick-action" onClick={() => navigate('inventory')}><span>Consultar estoque</span><small>Veja saldos por produto, lote e local</small></button>}{productsWrite && <button className="quick-action" onClick={() => navigate('products')}><span>Novo produto</span><small>Cadastre produtos e conversoes</small></button>}{batchesWrite && <button className="quick-action" onClick={() => navigate('batches')}><span>Novo lote</span><small>Informe fabricacao, lote e validade</small></button>}</section><section className="summary-section"><p className="eyebrow">Visao atual</p><h2>Resumo dos cadastros</h2>{loading ? <LoadingState label="Carregando resumo" /> : <div className="summary-grid"><Metric label="Produtos" value={counts.products} action="Ver produtos" onClick={() => navigate('products')} /><Metric label="Lotes" value={counts.batches} action="Ver lotes" onClick={() => navigate('batches')} />{inventory && <Metric label="Posicoes em estoque" value={counts.positions} action="Consultar saldo" onClick={() => navigate('inventory')} />}</div>}</section></>;
}
function Metric({ label, value, action, onClick }: { label: string; value: number; action: string; onClick: () => void }) { return <article className="metric"><span>{label}</span><strong>{value}</strong><button className="text-button" onClick={onClick}>{action}</button></article>; }

function OperationsPage({ navigate, onTransfer, onReview }: { navigate: Navigate; onTransfer: () => void; onReview: () => void }) {
  return <><PageHeader eyebrow="Movimentacao" title="Operacoes de estoque" description="Escolha a movimentacao que deseja registrar." /><section className="quick-actions"><button className="quick-action primary-action" onClick={onReview}><span>Revisar produtos</span><small>Distribua os produtos que possuem saldo em Revisar</small></button><button className="quick-action" onClick={() => navigate('new-entry')}><span>Nova entrada</span><small>Receba produtos de uma origem externa</small></button><button className="quick-action" onClick={() => navigate('new-exit')}><span>Nova saida</span><small>Envie produtos disponiveis para um destino externo</small></button><button className="quick-action" onClick={onTransfer}><span>Transferir</span><small>Mova saldo entre dois locais controlados</small></button></section></>;
}

function ProductsPage({ canWrite }: { canWrite: boolean }) {
  const [products, setProducts] = useState<Product[]>([]); const [selected, setSelected] = useState<Product | null>(null); const [conversions, setConversions] = useState<UnitConversion[]>([]);
  const [search, setSearch] = useState(''); const [error, setError] = useState(''); const [success, setSuccess] = useState(''); const [editing, setEditing] = useState<Product | null>(null);
  const [showForm, setShowForm] = useState(false); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [confirming, setConfirming] = useState<Product | null>(null);
  const load = useCallback(async () => { setLoading(true); try { setProducts((await api.get<Paginated<Product>>(`/products?limit=100&search=${encodeURIComponent(search)}`)).items); setError(''); } catch (caught) { setError(messageFrom(caught)); } finally { setLoading(false); } }, [search]);
  useEffect(() => { const timeout = window.setTimeout(() => void load(), 250); return () => window.clearTimeout(timeout); }, [load]);
  function openForm(product: Product | null) { setEditing(product); setShowForm(true); window.scrollTo({ top: 0, behavior: 'smooth' }); }
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); const form = new FormData(event.currentTarget); try { const payload = { code: form.get('code'), name: form.get('name'), defaultUnit: form.get('defaultUnit') }; if (editing) await api.patch(`/products/${editing.id}`, payload); else await api.post('/products', payload); setSuccess(editing ? 'Produto atualizado com sucesso.' : 'Produto cadastrado com sucesso.'); setShowForm(false); setEditing(null); await load(); } catch (caught) { setError(messageFrom(caught)); } finally { setBusy(false); } }
  async function select(product: Product) { setSelected(product); try { setConversions(await api.get(`/products/${product.id}/conversions`)); } catch (caught) { setError(messageFrom(caught)); } }
  async function addConversion(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!selected) return; setBusy(true); const form = new FormData(event.currentTarget); try { await api.post(`/products/${selected.id}/conversions`, { fromUnit: form.get('fromUnit'), toUnit: form.get('toUnit'), factor: Number(form.get('factor')) }); setConversions(await api.get(`/products/${selected.id}/conversions`)); event.currentTarget.reset(); setSuccess('Conversao adicionada com sucesso.'); } catch (caught) { setError(messageFrom(caught)); } finally { setBusy(false); } }
  async function toggle(product: Product) { setBusy(true); try { await api.patch(`/products/${product.id}/status`, { active: !product.active }); setSuccess(product.active ? 'Produto inativado com sucesso.' : 'Produto ativado com sucesso.'); setConfirming(null); await load(); } catch (caught) { setError(messageFrom(caught)); } finally { setBusy(false); } }
  return <><PageHeader eyebrow="Cadastro base" title="Produtos" description="Consulte produtos e mantenha suas unidades e conversoes." action={canWrite && <button onClick={() => openForm(null)}>+ Novo produto</button>} />{success && <Notice kind="success" onClose={() => setSuccess('')}>{success}</Notice>}{error && <Notice kind="error" onClose={() => setError('')}>{error}</Notice>}{showForm && <section className="surface form-panel"><PanelHeading eyebrow={editing ? 'Edicao' : 'Novo cadastro'} title={editing ? 'Editar produto' : 'Cadastrar produto'} onClose={() => setShowForm(false)} /><form key={editing?.id ?? 'new'} className="form-grid" onSubmit={(event) => void save(event)}><RequiredField label="Codigo"><input name="code" defaultValue={editing?.code} required maxLength={60} autoFocus /></RequiredField><RequiredField label="Nome"><input name="name" defaultValue={editing?.name} required maxLength={200} /></RequiredField><RequiredField label="Unidade padrao"><input name="defaultUnit" defaultValue={editing?.defaultUnit} required maxLength={20} /></RequiredField><FormActions busy={busy} saveLabel="Salvar produto" onCancel={() => setShowForm(false)} /></form></section>}<div className="content-grid"><section className="surface list-panel"><div className="toolbar"><label className="search-field">Buscar produto<input type="search" placeholder="Codigo ou nome" value={search} onChange={(event) => setSearch(event.target.value)} /></label></div>{loading ? <LoadingState label="Carregando produtos" /> : products.length === 0 ? <EmptyState title={search ? 'Nenhum produto encontrado' : 'Nenhum produto cadastrado'} description={search ? 'Revise o termo de busca.' : 'Cadastre o primeiro produto para comecar.'} action={canWrite && !search ? <button onClick={() => openForm(null)}>Cadastrar produto</button> : undefined} /> : <div className="responsive-table"><table><thead><tr><th>Codigo</th><th>Produto</th><th>Unidade</th><th>Status</th><th>Acoes</th></tr></thead><tbody>{products.map((product) => <tr key={product.id} className={selected?.id === product.id ? 'selected' : ''}><td data-label="Codigo"><button className="text-button" onClick={() => void select(product)}>{product.code}</button></td><td data-label="Produto">{product.name}</td><td data-label="Unidade">{product.defaultUnit}</td><td data-label="Status"><Status active={product.active} /></td><td data-label="Acoes"><div className="row-actions">{canWrite && <><button className="secondary" onClick={() => openForm(product)}>Editar</button><button className="secondary" onClick={() => product.active ? setConfirming(product) : void toggle(product)}>{product.active ? 'Inativar' : 'Ativar'}</button></>}</div></td></tr>)}</tbody></table></div>}</section><aside className="surface detail-panel"><p className="eyebrow">Detalhes</p><h2>{selected?.name ?? 'Selecione um produto'}</h2>{selected ? <><dl><dt>Codigo</dt><dd>{selected.code}</dd><dt>Unidade</dt><dd>{selected.defaultUnit}</dd><dt>Status</dt><dd>{selected.active ? 'Ativo' : 'Inativo'}</dd></dl><div className="divider" /><h3>Conversoes de unidade</h3>{conversions.length === 0 ? <p className="muted">Nenhuma conversao cadastrada.</p> : <ul className="conversion-list">{conversions.map((item) => <li key={item.id}><strong>{item.fromUnit}</strong><span>1 × {item.factor} = {item.factor} {item.toUnit}</span></li>)}</ul>}{canWrite && <form className="compact-form" onSubmit={(event) => void addConversion(event)}><label>Origem<input name="fromUnit" required /></label><label>Destino<input name="toUnit" required /></label><label>Fator<input name="factor" type="number" min="0.000001" step="0.000001" required /></label><button disabled={busy}>{busy ? 'Adicionando...' : 'Adicionar conversao'}</button></form>}</> : <p className="muted">Toque no codigo de um produto para ver os detalhes.</p>}</aside></div><ConfirmDialog open={Boolean(confirming)} title="Inativar produto?" description={`O produto ${confirming?.name ?? ''} deixara de aparecer nas selecoes operacionais.`} confirmLabel="Inativar produto" busy={busy} onCancel={() => setConfirming(null)} onConfirm={() => { if (confirming) void toggle(confirming); }} /></>;
}

function BatchesPage({ canWrite }: { canWrite: boolean }) {
  const [batches, setBatches] = useState<Batch[]>([]); const [products, setProducts] = useState<Product[]>([]); const [editing, setEditing] = useState<Batch | null>(null);
  const [code, setCode] = useState(''); const [manufacturingDate, setManufacturingDate] = useState(''); const [expirationDate, setExpirationDate] = useState('');
  const [showForm, setShowForm] = useState(false); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [resolving, setResolving] = useState(false); const [error, setError] = useState(''); const [success, setSuccess] = useState('');
  const load = useCallback(async () => { setLoading(true); try { const [batchData, productData] = await Promise.all([api.get<Paginated<Batch>>('/batches?limit=100'), api.get<Paginated<Product>>('/products?limit=100&active=true')]); setBatches(batchData.items); setProducts(productData.items); setError(''); } catch (caught) { setError(messageFrom(caught)); } finally { setLoading(false); } }, []);
  useEffect(() => { const timeout = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timeout); }, [load]);
  function reset() { setEditing(null); setCode(''); setManufacturingDate(''); setExpirationDate(''); }
  function open(batch: Batch | null) { reset(); if (batch) { setEditing(batch); setCode(batch.code); setManufacturingDate(batch.manufacturingDate); setExpirationDate(batch.expirationDate); } setShowForm(true); window.scrollTo({ top: 0, behavior: 'smooth' }); }
  async function resolve(values: { code?: string; manufacturingDate?: string }) { if (!(values.code ?? values.manufacturingDate)) return; setResolving(true); try { const result = await api.post<ResolvedBatchCode>('/batches/resolve-code', values); setCode(result.code); setManufacturingDate(result.manufacturingDate); setError(''); } catch (caught) { setError(messageFrom(caught)); } finally { setResolving(false); } }
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); const form = new FormData(event.currentTarget); try { const payload = { code, manufacturingDate, expirationDate }; if (editing) await api.patch(`/batches/${editing.id}`, payload); else await api.post('/batches', { ...payload, productId: form.get('productId') }); setSuccess(editing ? 'Lote atualizado com sucesso.' : 'Lote cadastrado com sucesso.'); reset(); setShowForm(false); await load(); } catch (caught) { setError(messageFrom(caught)); } finally { setBusy(false); } }
  const productName = (batch: Batch) => products.find((product) => product.id === batch.productId)?.name ?? batch.product?.name ?? 'Produto';
  return <><PageHeader eyebrow="Rastreabilidade" title="Lotes" description="A fabricacao e o codigo CONSERVADI representam a mesma informacao." action={canWrite && <button onClick={() => open(null)}>+ Novo lote</button>} />{success && <Notice kind="success" onClose={() => setSuccess('')}>{success}</Notice>}{error && <Notice kind="error" onClose={() => setError('')}>{error}</Notice>}{showForm && <section className="surface form-panel"><PanelHeading eyebrow={editing ? 'Edicao' : 'Novo cadastro'} title={editing ? 'Editar lote' : 'Cadastrar lote'} onClose={() => setShowForm(false)} /><form key={editing?.id ?? 'new'} className="form-grid batch-form" onSubmit={(event) => void save(event)}><RequiredField label="Produto"><select name="productId" defaultValue={editing?.productId ?? ''} required disabled={Boolean(editing)}><option value="">Selecione</option>{products.map((product) => <option key={product.id} value={product.id}>{product.code} — {product.name}</option>)}</select></RequiredField><div className="linked-fields"><RequiredField label="Fabricacao"><input type="date" value={manufacturingDate} required onChange={(event) => { setManufacturingDate(event.target.value); void resolve({ manufacturingDate: event.target.value }); }} /></RequiredField><span className="link-indicator">gera</span><RequiredField label="Codigo do lote"><input value={code} maxLength={6} pattern="[CONSERVADIconservadi]{6}" required onChange={(event) => setCode(event.target.value.toUpperCase())} onBlur={() => void resolve({ code })} /><small>{resolving ? 'Calculando...' : '6 letras CONSERVADI'}</small></RequiredField></div><RequiredField label="Validade"><input type="date" value={expirationDate} min={manufacturingDate} required onChange={(event) => setExpirationDate(event.target.value)} /></RequiredField><FormActions busy={busy || resolving} saveLabel="Salvar lote" onCancel={() => setShowForm(false)} /></form></section>}<section className="surface list-panel">{loading ? <LoadingState label="Carregando lotes" /> : batches.length === 0 ? <EmptyState title="Nenhum lote cadastrado" description="Cadastre o primeiro lote informando fabricacao e validade." action={canWrite ? <button onClick={() => open(null)}>Cadastrar lote</button> : undefined} /> : <div className="responsive-table"><table><thead><tr><th>Lote</th><th>Produto</th><th>Fabricacao</th><th>Validade</th><th>Acoes</th></tr></thead><tbody>{batches.map((batch) => <tr key={batch.id}><td data-label="Lote"><strong>{batch.code}</strong></td><td data-label="Produto">{productName(batch)}</td><td data-label="Fabricacao">{formatDate(batch.manufacturingDate)}</td><td data-label="Validade">{formatDate(batch.expirationDate)}</td><td data-label="Acoes"><div className="row-actions">{canWrite && <button className="secondary" onClick={() => open(batch)}>Editar lote</button>}</div></td></tr>)}</tbody></table></div>}</section></>;
}

function InventoryPage({ onTransfer, onReview }: { onTransfer?: (prefill: TransferPrefill) => void; onReview?: (prefill: ReviewPrefill) => void }) {
  const [positions, setPositions] = useState<StockPosition[]>([]); const [products, setProducts] = useState<Product[]>([]); const [batches, setBatches] = useState<Batch[]>([]); const [locations, setLocations] = useState<StockLocation[]>([]); const [selected, setSelected] = useState<StockPosition | null>(null);
  const [productId, setProductId] = useState(''); const [batchId, setBatchId] = useState(''); const [stockLocationId, setStockLocationId] = useState(''); const [showFilters, setShowFilters] = useState(false); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const load = useCallback(async () => { setLoading(true); const query = new URLSearchParams({ limit: '100' }); if (productId) query.set('productId', productId); if (batchId) query.set('batchId', batchId); if (stockLocationId) query.set('stockLocationId', stockLocationId); try { const [positionData, productData, batchData, locationData] = await Promise.all([api.get<Paginated<StockPosition>>(`/stock-positions?${query}`), api.get<Paginated<Product>>('/products?limit=100&active=true'), api.get<Paginated<Batch>>('/batches?limit=100'), api.get<Paginated<StockLocation>>('/stocks?limit=100&active=true')]); setPositions(positionData.items); setProducts(productData.items); setBatches(batchData.items); setLocations(locationData.items); setError(''); } catch (caught) { setError(messageFrom(caught)); } finally { setLoading(false); } }, [batchId, productId, stockLocationId]);
  useEffect(() => { const timeout = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timeout); }, [load]);
  const filters = [productId, batchId, stockLocationId].filter(Boolean).length; const availableBatches = productId ? batches.filter((batch) => batch.productId === productId) : batches; const clear = () => { setProductId(''); setBatchId(''); setStockLocationId(''); };
  return <><PageHeader eyebrow="Consulta operacional" title="Estoque atual" description="Saldo consolidado por produto, lote e local." action={<button className="secondary filter-toggle" onClick={() => setShowFilters((value) => !value)}>Filtros{filters ? ` (${filters})` : ''}</button>} />{error && <Notice kind="error">{error}</Notice>}<section className={`surface filters-panel ${showFilters ? 'filters-open' : ''}`}><div className="filter-grid"><label>Produto<select value={productId} onChange={(event) => { setProductId(event.target.value); setBatchId(''); }}><option value="">Todos</option>{products.map((product) => <option key={product.id} value={product.id}>{product.code} — {product.name}</option>)}</select></label><label>Lote<select value={batchId} onChange={(event) => setBatchId(event.target.value)}><option value="">Todos</option>{availableBatches.map((batch) => <option key={batch.id} value={batch.id}>{batch.code}</option>)}</select></label><label>Local<select value={stockLocationId} onChange={(event) => setStockLocationId(event.target.value)}><option value="">Todos</option>{locations.map((location) => <option key={location.id} value={location.id}>{location.code} — {location.name}</option>)}</select></label></div>{filters > 0 && <button className="text-button" onClick={clear}>Limpar filtros</button>}</section><div className="content-grid inventory-grid"><section className="surface list-panel">{loading ? <LoadingState label="Consultando estoque" /> : positions.length === 0 ? <EmptyState title={filters ? 'Nenhuma posicao encontrada' : 'Estoque sem posicoes'} description={filters ? 'Ajuste ou limpe os filtros.' : 'As posicoes aparecerao quando operacoes de estoque forem registradas.'} action={filters ? <button className="secondary" onClick={clear}>Limpar filtros</button> : undefined} /> : <div className="responsive-table"><table><thead><tr><th>Produto</th><th>Lote</th><th>Fabricacao</th><th>Validade</th><th>Local</th><th>Quantidade</th></tr></thead><tbody>{positions.map((position) => <tr key={position.id} className={selected?.id === position.id ? 'selected' : ''} onClick={() => setSelected(position)} tabIndex={0} onKeyDown={(event) => { if (event.key === 'Enter') setSelected(position); }}><td data-label="Produto"><strong>{position.product.name}</strong><small className="cell-note">{position.product.code}</small></td><td data-label="Lote">{position.batch.code}</td><td data-label="Fabricacao">{formatDate(position.batch.manufacturingDate)}</td><td data-label="Validade">{formatDate(position.batch.expirationDate)}</td><td data-label="Local">{position.stockLocation.name}</td><td data-label="Quantidade"><strong className="quantity">{position.quantity} {position.product.defaultUnit}</strong></td></tr>)}</tbody></table></div>}</section>{selected && <aside className="surface detail-panel"><PanelHeading eyebrow="Detalhes da posicao" title={selected.product.name} onClose={() => setSelected(null)} /><dl><dt>Produto</dt><dd>{selected.product.code}</dd><dt>Lote</dt><dd>{selected.batch.code}</dd><dt>Fabricacao</dt><dd>{formatDate(selected.batch.manufacturingDate)}</dd><dt>Validade</dt><dd>{formatDate(selected.batch.expirationDate)}</dd><dt>Local</dt><dd>{selected.stockLocation.name}</dd><dt>Quantidade</dt><dd>{selected.quantity} {selected.product.defaultUnit}</dd></dl>{onReview && selected.stockLocation.reviewRole === 'SOURCE' && <button className="button-wide" onClick={() => onReview({ productId: selected.productId, batchId: selected.batchId })}>Realizar revisao</button>}{onTransfer && <button className="button-wide secondary" onClick={() => onTransfer({ originLocationId: selected.stockLocationId, productId: selected.productId, batchId: selected.batchId })}>Transferir esta posicao</button>}</aside>}</div></>;
}

function StocksPage({ canWrite }: { canWrite: boolean }) {
  const [locations, setLocations] = useState<StockLocation[]>([]); const [editing, setEditing] = useState<StockLocation | null>(null); const [showForm, setShowForm] = useState(false); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [confirming, setConfirming] = useState<StockLocation | null>(null); const [error, setError] = useState(''); const [success, setSuccess] = useState('');
  const load = useCallback(async () => { setLoading(true); try { setLocations((await api.get<Paginated<StockLocation>>('/stocks?limit=100')).items); setError(''); } catch (caught) { setError(messageFrom(caught)); } finally { setLoading(false); } }, []); useEffect(() => { const timeout = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timeout); }, [load]);
  function open(location: StockLocation | null) { setEditing(location); setShowForm(true); window.scrollTo({ top: 0, behavior: 'smooth' }); }
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setBusy(true); const form = new FormData(event.currentTarget); const payload = { code: form.get('code'), name: form.get('name'), description: form.get('description') || null, kind: form.get('kind') as StockLocationKind, parentId: form.get('parentId') || null }; try { if (editing) await api.patch(`/stocks/${editing.id}`, payload); else await api.post('/stocks', payload); setSuccess(editing ? 'Local atualizado com sucesso.' : 'Local cadastrado com sucesso.'); setShowForm(false); setEditing(null); await load(); } catch (caught) { setError(messageFrom(caught)); } finally { setBusy(false); } }
  async function toggle(location: StockLocation) { setBusy(true); try { await api.patch(`/stocks/${location.id}/status`, { active: !location.active }); setSuccess(location.active ? 'Local inativado com sucesso.' : 'Local ativado com sucesso.'); setConfirming(null); await load(); } catch (caught) { setError(messageFrom(caught)); } finally { setBusy(false); } }
  const parents = locations.filter((item) => item.kind === 'STOCK' && item.active); const kindLabel = (kind: StockLocationKind) => ({ STOCK: 'Estoque', SUBSTOCK: 'Subestoque', EXTERNAL: 'Origem/destino externo' })[kind];
  return <><PageHeader eyebrow="Estrutura logica" title="Estoques e locais" description="Locais usados como origem, destino e classificacao do saldo." action={canWrite && <button onClick={() => open(null)}>+ Novo local</button>} />{success && <Notice kind="success" onClose={() => setSuccess('')}>{success}</Notice>}{error && <Notice kind="error">{error}</Notice>}{showForm && <section className="surface form-panel"><PanelHeading eyebrow={editing ? 'Edicao' : 'Novo cadastro'} title={editing ? 'Editar local' : 'Cadastrar local'} onClose={() => setShowForm(false)} /><form key={editing?.id ?? 'new'} className="form-grid" onSubmit={(event) => void save(event)}><RequiredField label="Codigo"><input name="code" defaultValue={editing?.code} required /></RequiredField><RequiredField label="Nome"><input name="name" defaultValue={editing?.name} required /></RequiredField><RequiredField label="Tipo"><select name="kind" defaultValue={editing?.kind ?? 'STOCK'}><option value="STOCK">Estoque</option><option value="SUBSTOCK">Subestoque</option><option value="EXTERNAL">Origem/destino externo</option></select></RequiredField><label>Estoque pai<select name="parentId" defaultValue={editing?.parentId ?? ''}><option value="">Nenhum</option>{parents.filter((item) => item.id !== editing?.id).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><small>Obrigatorio somente para subestoques.</small></label><label className="wide">Descricao<input name="description" defaultValue={editing?.description ?? ''} /></label><FormActions busy={busy} saveLabel="Salvar local" onCancel={() => setShowForm(false)} /></form></section>}<section className="surface list-panel">{loading ? <LoadingState label="Carregando locais" /> : locations.length === 0 ? <EmptyState title="Nenhum local cadastrado" description="Cadastre um local para organizar a operacao." action={canWrite ? <button onClick={() => open(null)}>Cadastrar local</button> : undefined} /> : <div className="responsive-table"><table><thead><tr><th>Codigo</th><th>Nome</th><th>Tipo</th><th>Estoque pai</th><th>Status</th><th>Acoes</th></tr></thead><tbody>{locations.map((location) => <tr key={location.id}><td data-label="Codigo"><strong>{location.code}</strong></td><td data-label="Nome">{location.name}</td><td data-label="Tipo">{kindLabel(location.kind)}</td><td data-label="Estoque pai">{locations.find((item) => item.id === location.parentId)?.name ?? '—'}</td><td data-label="Status"><Status active={location.active} /></td><td data-label="Acoes"><div className="row-actions">{canWrite && <><button className="secondary" onClick={() => open(location)}>Editar</button><button className="secondary" onClick={() => location.active ? setConfirming(location) : void toggle(location)}>{location.active ? 'Inativar' : 'Ativar'}</button></>}</div></td></tr>)}</tbody></table></div>}</section><ConfirmDialog open={Boolean(confirming)} title="Inativar local?" description={`O local ${confirming?.name ?? ''} deixara de aparecer nas selecoes operacionais.`} confirmLabel="Inativar local" busy={busy} onCancel={() => setConfirming(null)} onConfirm={() => { if (confirming) void toggle(confirming); }} /></>;
}

interface EntryDraftItem { key: string; productId: string; batchId: string; quantity: number }

function NewEntryPage({ canCreateBatch, onCreated }: { canCreateBatch: boolean; onCreated: (id: string) => void }) {
  const [products, setProducts] = useState<Product[]>([]); const [batches, setBatches] = useState<Batch[]>([]); const [locations, setLocations] = useState<StockLocation[]>([]);
  const [originId, setOriginId] = useState(''); const [destinationId, setDestinationId] = useState(''); const [observation, setObservation] = useState('');
  const [productId, setProductId] = useState(''); const [batchId, setBatchId] = useState(''); const [quantity, setQuantity] = useState(''); const [items, setItems] = useState<EntryDraftItem[]>([]);
  const [confirming, setConfirming] = useState(false); const [quickBatch, setQuickBatch] = useState(false); const [busy, setBusy] = useState(false); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const [requestKey, setRequestKey] = useState(() => crypto.randomUUID());
  const load = useCallback(async () => { setLoading(true); try { const [productData, batchData, locationData] = await Promise.all([api.get<Paginated<Product>>('/products?limit=100&active=true'), api.get<Paginated<Batch>>('/batches?limit=100'), api.get<Paginated<StockLocation>>('/stocks?limit=100&active=true')]); setProducts(productData.items); setBatches(batchData.items); setLocations(locationData.items); } catch (caught) { setError(messageFrom(caught)); } finally { setLoading(false); } }, []);
  useEffect(() => { const timeout = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timeout); }, [load]);
  const origins = locations.filter((location) => location.kind === 'EXTERNAL'); const destinations = locations.filter((location) => location.kind !== 'EXTERNAL'); const availableBatches = batches.filter((batch) => batch.productId === productId);
  const productFor = (id: string) => products.find((product) => product.id === id); const batchFor = (id: string) => batches.find((batch) => batch.id === id); const locationFor = (id: string) => locations.find((location) => location.id === id);
  function addItem(event: FormEvent) { event.preventDefault(); const numericQuantity = Number(quantity); if (!productId || !batchId || !Number.isFinite(numericQuantity) || numericQuantity <= 0) { setError('Selecione produto e lote e informe uma quantidade positiva.'); return; } setItems((current) => [...current, { key: crypto.randomUUID(), productId, batchId, quantity: numericQuantity }]); setBatchId(''); setQuantity(''); setError(''); }
  async function createBatch(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (!productId) return; setBusy(true); const form = new FormData(event.currentTarget); try { const created = await api.post<Batch>('/batches', { productId, manufacturingDate: form.get('manufacturingDate'), expirationDate: form.get('expirationDate') }); setBatches((current) => [...current, created]); setBatchId(created.id); setQuickBatch(false); } catch (caught) { setError(messageFrom(caught)); } finally { setBusy(false); } }
  async function submit() { setBusy(true); setError(''); try { const movement = await api.post<Movement>('/movements/external-entries', { requestKey, originLocationId: originId, destinationLocationId: destinationId, observation: observation || undefined, items: items.map(({ productId: itemProductId, batchId: itemBatchId, quantity: itemQuantity }) => ({ productId: itemProductId, batchId: itemBatchId, quantity: itemQuantity })) }); setRequestKey(crypto.randomUUID()); setConfirming(false); onCreated(movement.id); } catch (caught) { setError(messageFrom(caught)); setConfirming(false); } finally { setBusy(false); } }
  if (loading) return <LoadingState label="Preparando nova entrada" />;
  return <><PageHeader eyebrow="Movimentacao" title="Nova entrada externa" description="A entrada sera efetivada no estoque assim que voce confirmar." />{error && <Notice kind="error" onClose={() => setError('')}>{error}</Notice>}<section className="surface form-panel"><h2>Origem e destino</h2><div className="form-grid"><RequiredField label="Origem externa"><select value={originId} onChange={(event) => setOriginId(event.target.value)} required><option value="">Selecione</option>{origins.map((location) => <option key={location.id} value={location.id}>{location.name}</option>)}</select></RequiredField><RequiredField label="Destino controlado"><select value={destinationId} onChange={(event) => setDestinationId(event.target.value)} required><option value="">Selecione</option>{destinations.map((location) => <option key={location.id} value={location.id}>{location.name}</option>)}</select></RequiredField><label className="wide">Observacao<textarea value={observation} onChange={(event) => setObservation(event.target.value)} maxLength={1000} rows={3} /></label></div></section><section className="surface form-panel"><h2>Adicionar item</h2><form className="form-grid" onSubmit={addItem}><RequiredField label="Produto"><select value={productId} onChange={(event) => { setProductId(event.target.value); setBatchId(''); }}><option value="">Selecione</option>{products.map((product) => <option key={product.id} value={product.id}>{product.code} - {product.name}</option>)}</select></RequiredField><RequiredField label="Lote"><select value={batchId} onChange={(event) => setBatchId(event.target.value)} disabled={!productId}><option value="">Selecione</option>{availableBatches.map((batch) => <option key={batch.id} value={batch.id}>{batch.code} - validade {formatDate(batch.expirationDate)}</option>)}</select>{canCreateBatch && productId && <button type="button" className="text-button" onClick={() => setQuickBatch(true)}>+ Criar lote para este produto</button>}</RequiredField><RequiredField label="Quantidade"><input type="number" min="0.000001" step="0.000001" value={quantity} onChange={(event) => setQuantity(event.target.value)} /></RequiredField><div className="form-actions"><button>Adicionar item</button></div></form></section><section className="surface list-panel"><h2>Itens da entrada ({items.length})</h2>{items.length === 0 ? <EmptyState title="Nenhum item adicionado" description="Selecione produto, lote e quantidade acima." /> : <div className="entry-items">{items.map((item) => <article key={item.key} className="entry-item"><div><strong>{productFor(item.productId)?.name}</strong><span>Lote {batchFor(item.batchId)?.code} - {item.quantity} {productFor(item.productId)?.defaultUnit}</span></div><button className="secondary" onClick={() => setItems((current) => current.filter((candidate) => candidate.key !== item.key))}>Remover</button></article>)}</div>}<button className="button-wide" disabled={!originId || !destinationId || items.length === 0 || busy} onClick={() => setConfirming(true)}>Revisar e confirmar entrada</button></section>{quickBatch && <div className="dialog-backdrop"><section className="dialog" role="dialog" aria-modal="true" aria-labelledby="quick-batch-title"><p className="eyebrow">Novo lote</p><h2 id="quick-batch-title">{productFor(productId)?.name}</h2><form className="form-grid" onSubmit={(event) => void createBatch(event)}><RequiredField label="Fabricacao"><input name="manufacturingDate" type="date" required autoFocus /></RequiredField><RequiredField label="Validade"><input name="expirationDate" type="date" required /></RequiredField><FormActions busy={busy} saveLabel="Criar e selecionar" onCancel={() => setQuickBatch(false)} /></form></section></div>}{confirming && <div className="dialog-backdrop"><section className="dialog confirmation-dialog" role="dialog" aria-modal="true" aria-labelledby="entry-confirm-title"><p className="eyebrow">Confirmacao</p><h2 id="entry-confirm-title">Efetivar esta entrada?</h2><p>{locationFor(originId)?.name} para {locationFor(destinationId)?.name}, com {items.length} item(ns).</p><ul>{items.map((item) => <li key={item.key}>{productFor(item.productId)?.name} / {batchFor(item.batchId)?.code}: <strong>{item.quantity} {productFor(item.productId)?.defaultUnit}</strong></li>)}</ul><p>O saldo do destino sera aumentado e o registro ficara imutavel no historico.</p><div className="dialog-actions"><button className="secondary" disabled={busy} onClick={() => setConfirming(false)}>Voltar</button><button disabled={busy} onClick={() => void submit()}>{busy ? 'Efetivando...' : 'Confirmar entrada'}</button></div></section></div>}</>;
}

function MovementsPage({ initialId, success }: { initialId?: string; success?: string }) {
  const [movements, setMovements] = useState<Movement[]>([]);
  const [selected, setSelected] = useState<Movement | null>(null);
  const [locations, setLocations] = useState<StockLocation[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [filters, setFilters] = useState({ type: '', dateFrom: '', dateTo: '', originLocationId: '', destinationLocationId: '', productId: '' });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const label = (type: Movement['type']) => ({
    ENTRADA_EXTERNA: 'Entrada externa',
    SAIDA_EXTERNA: 'Saida externa',
    TRANSFERENCIA_INTERNA: 'Transferencia interna',
    REVISAO: 'Revisao',
  })[type];
  const load = useCallback(async () => {
    setLoading(true);
    const params = new URLSearchParams({ limit: '100' });
    Object.entries(filters).forEach(([key, value]) => {
      if (!value) return;
      const isDate = key === 'dateFrom' || key === 'dateTo';
      params.set(key, isDate ? new Date(`${value}T${key === 'dateFrom' ? '00:00:00.000' : '23:59:59.999'}`).toISOString() : value);
    });
    try {
      const [movementData, locationData, productData] = await Promise.all([
        api.get<Paginated<Movement>>(`/movements?${params}`),
        api.get<Paginated<StockLocation>>('/stocks?limit=100'),
        api.get<Paginated<Product>>('/products?limit=100'),
      ]);
      setMovements(movementData.items);
      setLocations(locationData.items);
      setProducts(productData.items);
      if (initialId) setSelected(await api.get<Movement>(`/movements/${initialId}`));
    } catch (caught) {
      setError(messageFrom(caught));
    } finally {
      setLoading(false);
    }
  }, [filters, initialId]);
  useEffect(() => { const timeout = window.setTimeout(() => void load(), 0); return () => window.clearTimeout(timeout); }, [load]);
  return <>
    <PageHeader eyebrow="Rastreabilidade" title="Historico de movimentacoes" description="Entradas, saidas, transferencias e revisoes efetivadas permanecem imutaveis." />
    {success && <Notice kind="success">{success}</Notice>}
    {error && <Notice kind="error">{error}</Notice>}
    <section className="surface filters-panel filters-open"><div className="filter-grid">
      <label>Tipo<select value={filters.type} onChange={(event) => setFilters({ ...filters, type: event.target.value })}><option value="">Todos</option><option value="ENTRADA_EXTERNA">Entrada externa</option><option value="SAIDA_EXTERNA">Saida externa</option><option value="TRANSFERENCIA_INTERNA">Transferencia interna</option><option value="REVISAO">Revisao</option></select></label>
      <label>De<input type="date" value={filters.dateFrom} onChange={(event) => setFilters({ ...filters, dateFrom: event.target.value })} /></label>
      <label>Ate<input type="date" value={filters.dateTo} onChange={(event) => setFilters({ ...filters, dateTo: event.target.value })} /></label>
      <label>Origem<select value={filters.originLocationId} onChange={(event) => setFilters({ ...filters, originLocationId: event.target.value })}><option value="">Todas</option>{locations.map((location) => <option key={location.id} value={location.id}>{location.name}</option>)}</select></label>
      <label>Destino<select value={filters.destinationLocationId} onChange={(event) => setFilters({ ...filters, destinationLocationId: event.target.value })}><option value="">Todos</option>{locations.map((location) => <option key={location.id} value={location.id}>{location.name}</option>)}</select></label>
      <label>Produto<select value={filters.productId} onChange={(event) => setFilters({ ...filters, productId: event.target.value })}><option value="">Todos</option>{products.map((product) => <option key={product.id} value={product.id}>{product.name}</option>)}</select></label>
    </div></section>
    <div className="content-grid"><section className="surface list-panel">{loading ? <LoadingState label="Carregando historico" /> : movements.length === 0 ? <EmptyState title="Nenhuma movimentacao encontrada" description="Ajuste os filtros ou registre uma operacao de estoque." /> : <div className="responsive-table"><table><thead><tr><th>Data</th><th>Tipo</th><th>Origem</th><th>Destino</th><th>Itens/quantidade</th></tr></thead><tbody>{movements.map((movement) => <tr key={movement.id} className={selected?.id === movement.id ? 'selected' : ''}><td data-label="Data"><button className="text-button" onClick={() => setSelected(movement)}>{formatDateTime(movement.occurredAt)}</button></td><td data-label="Tipo">{label(movement.type)}</td><td data-label="Origem">{movement.originLocation.name}</td><td data-label="Destino">{movement.destinationLocation?.name ?? 'Varios destinos'}</td><td data-label="Itens/quantidade">{movement.items.length} / {movement.items.reduce((total, item) => total + item.quantity, 0)}</td></tr>)}</tbody></table></div>}</section>
      <aside className="surface detail-panel"><p className="eyebrow">Detalhe imutavel</p><h2>{selected ? label(selected.type) : 'Selecione uma movimentacao'}</h2>{selected && <><dl><dt>Identificador</dt><dd>{selected.id}</dd><dt>Status</dt><dd><span className="badge active">Efetivada</span></dd><dt>Data/hora</dt><dd>{formatDateTime(selected.occurredAt)}</dd><dt>Responsavel</dt><dd>{selected.responsibleUser.username}</dd><dt>Origem</dt><dd>{selected.originLocation.name}</dd><dt>Destino</dt><dd>{selected.destinationLocation?.name ?? 'Distribuicao da revisao'}</dd><dt>Total de itens</dt><dd>{selected.items.length}</dd><dt>Quantidade total</dt><dd>{selected.items.reduce((total, item) => total + item.quantity, 0)}</dd><dt>Observacao</dt><dd>{selected.observation || '-'}</dd></dl><div className="divider" /><h3>Itens</h3><ul className="movement-detail-items">{selected.items.map((item) => <li key={item.id}><strong>{item.product.code} - {item.product.name}</strong><span>Lote {item.batch.code}</span><span>Fabricacao {formatDate(item.batch.manufacturingDate)} - validade {formatDate(item.batch.expirationDate)}</span><b>{item.quantity} {item.product.defaultUnit}</b>{item.distributions?.length > 0 && <ul className="distribution-detail">{item.distributions.map((distribution) => <li key={distribution.id}>{distribution.destinationLocation.name}: <strong>{distribution.quantity} {item.product.defaultUnit}</strong></li>)}</ul>}</li>)}</ul></>}</aside>
    </div>
  </>;
}

function PanelHeading({ eyebrow, title, onClose }: { eyebrow: string; title: string; onClose: () => void }) { return <div className="panel-heading"><div><p className="eyebrow">{eyebrow}</p><h2>{title}</h2></div><button type="button" className="secondary" onClick={onClose}>Fechar</button></div>; }
function RequiredField({ label, children }: { label: string; children: ReactNode }) { return <label><span>{label} <span className="required">*</span></span>{children}</label>; }
function FormActions({ busy, saveLabel, onCancel }: { busy: boolean; saveLabel: string; onCancel: () => void }) { return <div className="form-actions"><button disabled={busy}>{busy ? 'Salvando...' : saveLabel}</button><button type="button" className="secondary" onClick={onCancel} disabled={busy}>Cancelar</button></div>; }
function Status({ active }: { active: boolean }) { return <span className={`badge ${active ? 'active' : ''}`}>{active ? 'Ativo' : 'Inativo'}</span>; }
function MorePage({ navigate, username, logout, busy }: { navigate: Navigate; username: string; logout: () => void; busy: boolean }) { return <><PageHeader eyebrow="Mais" title="Cadastros e conta" description="Funcoes de apoio e dados da sua sessao." /><section className="more-grid"><button className="menu-card" onClick={() => navigate('products')}><span>Produtos</span><small>Cadastro e conversoes de unidade</small></button><button className="menu-card" onClick={() => navigate('batches')}><span>Lotes</span><small>Fabricacao, codigo e validade</small></button><button className="menu-card" onClick={() => navigate('stocks')}><span>Estoques e locais</span><small>Estrutura logica da operacao</small></button><article className="surface account-card"><p className="eyebrow">Sessao atual</p><h2>{username}</h2><p className="muted">Seu acesso segue as permissoes do perfil.</p><button className="secondary button-wide" onClick={logout} disabled={busy}>{busy ? 'Saindo...' : 'Sair do sistema'}</button></article></section></>; }
function NavButton({ active, onClick, children }: { active: boolean; onClick: () => void; children: ReactNode }) { return <button className={active ? 'current' : ''} onClick={onClick} aria-current={active ? 'page' : undefined}>{children}</button>; }

export function App() {
  const [user, setUser] = useState<UserSession | null>(null);
  const [checking, setChecking] = useState(true);
  const [loggingOut, setLoggingOut] = useState(false);
  const [page, setPage] = useState<Page>('home');
  const [selectedMovementId, setSelectedMovementId] = useState<string>();
  const [movementSuccess, setMovementSuccess] = useState<string>();
  const [transferPrefill, setTransferPrefill] = useState<TransferPrefill>();
  const [reviewPrefill, setReviewPrefill] = useState<ReviewPrefill>();
  useEffect(() => { void api.refresh().then((result) => setUser(result?.user ?? null)).finally(() => setChecking(false)); }, []);
  if (checking) return <main className="splash"><span className="spinner" /><p>Preparando seu ambiente...</p></main>;
  if (!user) return <Login onAuthenticated={(authenticated) => { setUser(authenticated); setPage('home'); }} />;
  const can = (permission: string) => user.permissions.includes(permission);
  const navigate: Navigate = (destination) => {
    if (destination !== 'new-transfer') setTransferPrefill(undefined);
    if (destination !== 'new-review') setReviewPrefill(undefined);
    setPage(destination);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };
  const openTransfer = (prefill?: TransferPrefill) => {
    setTransferPrefill(prefill);
    navigate('new-transfer');
  };
  const openReview = (prefill?: ReviewPrefill) => {
    setReviewPrefill(prefill);
    navigate('new-review');
  };
  const openHistory = () => {
    setSelectedMovementId(undefined);
    setMovementSuccess(undefined);
    navigate('movements');
  };
  const completeMovement = (id: string, message: string) => {
    setSelectedMovementId(id);
    setMovementSuccess(message);
    navigate('movements');
  };
  const logout = () => {
    setLoggingOut(true);
    void api.logout().finally(() => { setUser(null); setLoggingOut(false); });
  };
  return <div className="app-shell">
    <header className="topbar"><button className="brand" onClick={() => navigate('home')} aria-label="Ir para o inicio"><span>ER</span><strong>Estoque Revisao</strong></button><div className="user-area"><span className="user-name">{user.username}</span><button className="secondary desktop-logout" onClick={logout}>Sair</button></div></header>
    <aside className="sidebar"><nav aria-label="Navegacao principal"><NavButton active={page === 'home'} onClick={() => navigate('home')}>Inicio</NavButton>{can('movements.create') && <><NavButton active={page === 'new-review'} onClick={() => openReview()}>Revisar produtos</NavButton><NavButton active={page === 'new-entry'} onClick={() => navigate('new-entry')}>Nova entrada</NavButton><NavButton active={page === 'new-exit'} onClick={() => navigate('new-exit')}>Nova saida</NavButton><NavButton active={page === 'new-transfer'} onClick={() => openTransfer()}>Transferir</NavButton></>}{can('movements.read') && <NavButton active={page === 'movements'} onClick={openHistory}>Historico</NavButton>}{can('stock-positions.read') && <NavButton active={page === 'inventory'} onClick={() => navigate('inventory')}>Estoque atual</NavButton>}<NavButton active={page === 'products'} onClick={() => navigate('products')}>Produtos</NavButton><NavButton active={page === 'batches'} onClick={() => navigate('batches')}>Lotes</NavButton><NavButton active={page === 'stocks'} onClick={() => navigate('stocks')}>Estoques e locais</NavButton></nav><p className="sidebar-note">Operacao segura e rastreavel</p></aside>
    <main className="workspace">
      {page === 'home' && <HomePage navigate={navigate} onTransfer={() => openTransfer()} onReview={() => openReview()} inventory={can('stock-positions.read')} movementsCreate={can('movements.create')} movementsRead={can('movements.read')} productsWrite={can('products.create')} batchesWrite={can('batches.create')} />}
      {page === 'operations' && can('movements.create') && <OperationsPage navigate={navigate} onTransfer={() => openTransfer()} onReview={() => openReview()} />}
      {page === 'new-entry' && can('movements.create') && <NewEntryPage canCreateBatch={can('batches.create')} onCreated={(id) => completeMovement(id, 'Entrada registrada com sucesso.')} />}
      {page === 'new-exit' && can('movements.create') && <ExternalExitPage onCreated={(id) => completeMovement(id, 'Saida registrada com sucesso.')} />}
      {page === 'new-transfer' && can('movements.create') && <InternalTransferPage prefill={transferPrefill} onCreated={(id) => completeMovement(id, 'Transferencia realizada com sucesso.')} />}
      {page === 'new-review' && can('movements.create') && <ReviewPage prefill={reviewPrefill} onCreated={(id) => completeMovement(id, 'Revisao realizada com sucesso.')} />}
      {page === 'movements' && can('movements.read') && <MovementsPage initialId={selectedMovementId} success={movementSuccess} />}
      {page === 'products' && <ProductsPage canWrite={can('products.create') || can('products.update')} />}
      {page === 'batches' && <BatchesPage canWrite={can('batches.create') || can('batches.update')} />}
      {page === 'stocks' && <StocksPage canWrite={can('stocks.create') || can('stocks.update')} />}
      {page === 'inventory' && can('stock-positions.read') && <InventoryPage onTransfer={can('movements.create') ? openTransfer : undefined} onReview={can('movements.create') ? openReview : undefined} />}
      {page === 'more' && <MorePage navigate={navigate} username={user.username} logout={logout} busy={loggingOut} />}
    </main>
    <nav className="bottom-nav" aria-label="Navegacao principal mobile"><NavButton active={page === 'home'} onClick={() => navigate('home')}>Inicio</NavButton>{can('movements.create') && <NavButton active={page === 'operations' || page === 'new-entry' || page === 'new-exit' || page === 'new-transfer' || page === 'new-review'} onClick={() => navigate('operations')}>Operacoes</NavButton>}{can('movements.read') && <NavButton active={page === 'movements'} onClick={openHistory}>Historico</NavButton>}{can('stock-positions.read') && <NavButton active={page === 'inventory'} onClick={() => navigate('inventory')}>Estoque</NavButton>}<NavButton active={page === 'more' || page === 'products' || page === 'batches' || page === 'stocks'} onClick={() => navigate('more')}>Mais</NavButton></nav>
  </div>;
}
